def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    dirs = [(0, 1), (1, 0), (1, 1), (1, -1)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in dirs:
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue

                before = (r - dr, c - dc)
                after = (r2 + dr, c2 + dc)
                before_blocked = (0 <= before[0] < h and 0 <= before[1] < w
                                  and grid[before[0]][before[1]] != bg)
                after_blocked = (0 <= after[0] < h and 0 <= after[1] < w
                                 and grid[after[0]][after[1]] != bg)

                if after_blocked and not before_blocked:
                    rr, cc = before
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr -= dr
                        cc -= dc
                elif before_blocked and not after_blocked:
                    rr, cc = after
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc

    return out
